function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
function go(path){location.hash='#/'+path;}
async function api(path,body,method){const r=await fetch(C.API_BASE.replace(/\/$/,'')+'/api'+path,{method:method||(body?'POST':'GET'),headers:{'Content-Type':'application/json','X-Device-ID':dev,...(state.token?{Authorization:'Bearer '+state.token}:{})},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json();}catch{throw new Error('The backend did not return JSON. Check frontend/config.js and the Render health endpoint.');}if(!r.ok){const e=new Error(data.message||'Request failed');e.code=data.code;e.status=r.status;throw e;}return data;}
