async function notifications(){return C.DEMO_MODE?{notifications:demo.notifications,announcements:demo.announcements}:api('/notifications');}
let seenNoticeIds=null,noticeFingerprint='';
async function refreshNotices(announce=false){
 if(!state.user||!$('.shell'))return;
 try{const n=await notifications(),unread=n.notifications.filter(x=>!x.read_at),dot=$('.unread');if(dot){dot.hidden=!unread.length;dot.parentElement.setAttribute('aria-label','Notifications · '+unread.length+' unread');}
 const fingerprint=JSON.stringify([n.notifications.map(x=>[x.id,x.read_at]),n.announcements.map(x=>x.id||x.title)]),changed=noticeFingerprint&&noticeFingerprint!==fingerprint;noticeFingerprint=fingerprint;
 const ids=new Set(n.notifications.map(x=>x.id));if(announce&&seenNoticeIds){const fresh=n.notifications.filter(x=>!seenNoticeIds.has(x.id));fresh.slice(0,2).forEach(x=>toast(x.title+' — open Notifications to view.'));}seenNoticeIds=ids;
 const banner=$('.announcement>span');if(banner&&n.announcements[0])banner.textContent=n.announcements[0].title;
 if(announce&&changed&&location.hash==='#/notifications')await notificationPage();
 }catch{/* A transient poll failure must not interrupt writing or capture. */}
}
