 if(n===3){body=stepHeading(n,'A quick hello.<br>A safer community.','Take a fresh verification selfie. It will become your profile photo once your identity is verified.')+`<div class="notice">Face the camera in good light, remove sunglasses, and keep only your face in the frame. The local scanner compares it with your document photo. An administrator reviews the evidence; a still selfie cannot prove liveness.</div><div class="capture-thumbs">${captureThumb('selfie','Selfie')}</div><button class="btn secondary" data-action="capture-selfie">${I('camera')} Take verification selfie</button>${C.DEMO_MODE?'<button class="text-btn small" data-action="sample-selfie">Use sample marker</button>':''}<label class="check-label"><input id="biometricConsent" type="checkbox"><span>I explicitly consent to processing my document and face image for identity matching, liveness assessment, and fraud prevention as described in the <a class="text-btn" style="padding:0" href="#/privacy">privacy notice</a>. I understand local checks require human review and do not certify authenticity or liveness.</span></label><button class="btn" data-action="verify-identity">Verify identity & continue ${I('arrow')}</button>`;}
 if(n===4){body=stepHeading(n,'Tell us about yourself.','Use your chosen language to introduce yourself and describe your interests for at least one minute. Then complete 24 randomly selected translation questions.')+`<div class="notice">This introduction and assessment are unpaid. Webcam and microphone are required. In local-review mode, the recording is encrypted in the backend for an administrator fluent in your language. It is deleted after the decision, or during cleanup within about one minute of its seven-day expiry. Expired evidence is not accessible.</div><div class="camera-stage"><video id="interview-video" muted autoplay playsinline></video><div class="camera-placeholder" id="interview-placeholder">${I('mic')}<p>One minute. Your language. Your story.</p></div></div><div class="interview-timer" id="interview-timer">01:00</div><label class="check-label"><input type="checkbox" id="interviewConsent"><span>I consent to temporary video/audio processing for this language assessment. In local-review mode, encrypted evidence is retained until reviewed or for at most seven days. No fluency or liveness is automatically certified.</span></label><div class="row wrap"><button class="btn secondary" data-action="start-interview">${I('camera')} Start 60-second introduction</button><button class="btn" data-action="submit-interview" ${!state.recording?'disabled':''}>Evaluate introduction ${I('arrow')}</button></div>${C.DEMO_MODE?'<button class="text-btn small" data-action="sample-interview" style="margin-top:16px">Skip recording for preview · not a verified interview</button>':''}`;}
 if(n===5){let q;if(C.DEMO_MODE){const index=state.form.quizIndex||0;q={number:index+1,total:24,source:index<24?D.demoSentences[index%D.demoSentences.length]?.source:null,correct:state.form.quizCorrect||0};}else q=await api('/onboarding/quiz');state.quiz=q;
 body=stepHeading(n,'A small test.<br>A meaningful beginning.','Translate 24 randomly selected English sentences into your chosen language. At least 21 must preserve the meaning to continue.')+(q.reviewPending?`<div class="notice">Your answer is awaiting a fluent reviewer. No penalty or payment applies to this unpaid assessment.</div><button class="btn secondary" data-action="refresh-quiz">Check review status</button>`:q.source?`<span class="badge">Question ${q.number} / 24 · ${q.correct} correct</span><blockquote class="task-sentence" style="margin-left:0">${esc(q.source)}</blockquote><form id="quiz-form"><label for="quiz-answer">Your translation in ${esc(langName(state.user?.language||f.language||'sw'))}</label><textarea id="quiz-answer" name="answer" dir="auto" required minlength="2" maxlength="2000"></textarea><div id="quiz-feedback" aria-live="polite"></div><div class="row wrap" style="margin-top:18px"><button class="btn">Check translation ${I('arrow')}</button><button class="text-btn" type="button" data-action="listen-quiz">${I('volume')} Listen</button>${C.DEMO_MODE?'<button class="text-btn" type="button" data-action="sample-quiz">Fill Kiswahili sample</button>':''}</div></form>`:`<div class="notice ${q.correct<21?'warning':''}">Assessment complete: <strong>${q.correct} / 24</strong>. ${q.correct>=21?'You can now review your contributor agreement.':'At least 21 correct answers are needed. Review the guide and try again.'}</div><button class="btn" data-action="${q.correct>=21?'quiz-next':'quiz-reset'}">${q.correct>=21?'Review agreement':'Restart assessment'} ${I('arrow')}</button>`);}
